RDEV-CD-001:
NUMBER value.
INPUT(value).
IF (value < 0) {
    DISPLAYNL("NEGATIVE").
} ELSEIF (value == 0) {
    DISPLAYNL("ZERO").
} ELSE {
    DISPLAYNL("POSITIVE").
}

RDEV-CD-003:
NUMBER amount.
INPUT(amount).
IF (amount >= 100) {
    DISPLAYNL(0).
} ELSEIF (amount >= 50) {
    DISPLAYNL(5).
} ELSE {
    DISPLAYNL(10).
}

RDEV-LP-001:
NUMBER n.
INPUT(n).
LOOP (NUMBER i = 1 TILL i <= n, i++) {
    DISPLAYNL(i * i).
}

RDEV-FN-001:
FUNCTION cube(NUMBER value) {
    RETURN value * value * value.
} RETURNS NUMBER.
NUMBER inputValue.
INPUT(inputValue).
DISPLAYNL(cube(inputValue)).

RDEV-FN-003:
FUNCTION capAtTen(NUMBER value) {
    IF (value > 10) {
        RETURN 10.
    }
    RETURN value.
} RETURNS NUMBER.
NUMBER value.
INPUT(value).
DISPLAYNL(capAtTen(value)).

RDEV-CP-002:
NUMBER n.
INPUT(n).
LOGIC prime = TRUE.
IF (n < 2) {
    prime = FALSE.
}
LOOP (NUMBER divisor = 2 TILL divisor < n, divisor++) {
    IF (n % divisor == 0) {
        prime = FALSE.
    }
}
IF (prime) {
    DISPLAYNL("PRIME").
} ELSE {
    DISPLAYNL("NOT PRIME").
}

RDEV-CP-003:
IMPORT math.
NUMBER value.
INPUT(value).
NUMBER total = 0.
LOOP (value > 0) {
    total += value % 10.
    value = math.FLOOR(value / 10).
}
IF (total % 2 == 0) {
    DISPLAYNL("EVEN").
} ELSE {
    DISPLAYNL("ODD").
}
